INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1435347, 185963, 3080, '<td valign="top">Very nice crisp photo.  I like the focus and clarity a lot.  The main subject is the creek?  I wish it were more interesting looking.  To me, the whole photo seems to be the main subject with the creek really only being a small part of it.  I like the colors and the clouds formations really add interest to the photo.  Overall a really beautiful scene, one I personally don''t get to see every day.  ~Heather~</td>', 'Very nice crisp photo.  I like the focus and clarity a lot.  The main subject is the creek?  I wish it were more interesting looking.  To me, the whole photo seems to be the main subject with the creek really only being a small part of it.  I like the colors and the clouds formations really add interest to the photo.  Overall a really beautiful scene, one I personally don''t get to see every day.  ~Heather~', '2005-06-06 01:04:17.000000', NULL, 1),
(1435349, 185625, 3459, '<td valign="top">While you probably will get hammered with this image, I love it. An 11!<br/></td>', 'While you probably will get hammered with this image, I love it. An 11!', '2005-06-06 01:04:50.000000', NULL, 1),
(1435358, 186041, 3080, '<td valign="top">Second image that came up for me in the voting.  Wow.  I like this a lot.  very nice framing.  Focus and clarity are wonderful.  Great focus in all the right places.  I love the slight hint of the orange in the boat among all the blues.  Wonderfully horizontal horizon.  Too often this gets overlooked and is tilted, yours is dead on.  Wonderful job.  Excellent eye to capture this great image.  My only wish is that the boat could have somehow been a bit bigger, but non the less, a wonderful image. ~Heather~</td>', 'Second image that came up for me in the voting.  Wow.  I like this a lot.  very nice framing.  Focus and clarity are wonderful.  Great focus in all the right places.  I love the slight hint of the orange in the boat among all the blues.  Wonderfully horizontal horizon.  Too often this gets overlooked and is tilted, yours is dead on.  Wonderful job.  Excellent eye to capture this great image.  My only wish is that the boat could have somehow been a bit bigger, but non the less, a wonderful image. ~Heather~', '2005-06-06 01:06:48.000000', NULL, 1),
(1435363, 185378, 35827, '<td valign="top">great photo!</td>', 'great photo!', '2005-06-06 01:07:58.000000', NULL, 1),
(1435367, 184167, 34373, '<td valign="top">great shot!  I like the color and composition really well!</td>', 'great shot!  I like the color and composition really well!', '2005-06-06 01:09:15.000000', NULL, 1),
(1435371, 185597, 327, '<td valign="top">Beautiful setting, would love to be there! I think you''ve over sharpened a bit and maybe over saturated also. Not sure which or if both. It is lovely all the same.</td>', 'Beautiful setting, would love to be there! I think you''ve over sharpened a bit and maybe over saturated also. Not sure which or if both. It is lovely all the same.', '2005-06-06 01:10:07.000000', NULL, 1),
(1435373, 185733, 3080, '<td valign="top">Can''t really see his eyes well at all.  I wish we could.  I like the fact that it''s a horse behind a fence.  That is very clear and definately fits the challenge.  Focus is good on his mane.  Lighting seems just a bit dark to me.  The bright area is the part of his nose by the fence and that isn''t the most interesting part of the pic.  I like the blue background, nothing distracting there.  Something that catches my eye and I find a bit odd is right where his nose meets the fence to the right *his left* see where the fence kind of follows his nose for a bit and it''s not straight across?  Is this a lighting thing, some kind of optical illusion?  Overall a nice shot for the challenge, just wish lighting conditions were better.  ~Heather~</td>', 'Can''t really see his eyes well at all.  I wish we could.  I like the fact that it''s a horse behind a fence.  That is very clear and definately fits the challenge.  Focus is good on his mane.  Lighting seems just a bit dark to me.  The bright area is the part of his nose by the fence and that isn''t the most interesting part of the pic.  I like the blue background, nothing distracting there.  Something that catches my eye and I find a bit odd is right where his nose meets the fence to the right *his left* see where the fence kind of follows his nose for a bit and it''s not straight across?  Is this a lighting thing, some kind of optical illusion?  Overall a nice shot for the challenge, just wish lighting conditions were better.  ~Heather~', '2005-06-06 01:10:34.000000', NULL, 1),
(1435374, 185673, 36469, '<td valign="top">what an AMAZING shot</td>', 'what an AMAZING shot', '2005-06-06 01:10:42.000000', NULL, 1),
(1435378, 185673, 24599, '<td valign="top">i would have enjoyed this shot a lot more without the people. plus they look a little blurred. but its a great shot otherwise!</td>', 'i would have enjoyed this shot a lot more without the people. plus they look a little blurred. but its a great shot otherwise!', '2005-06-06 01:11:54.000000', NULL, 1),
(1435379, 183740, 327, '<td valign="top">I did some of my growing up in Cherry Hill and Haddonfield. Seeing this makes me think of the cedar streams, rivers that we used to canoe on. This is very nice, still, calm. Good sky also.</td>', 'I did some of my growing up in Cherry Hill and Haddonfield. Seeing this makes me think of the cedar streams, rivers that we used to canoe on. This is very nice, still, calm. Good sky also.', '2005-06-06 01:12:31.000000', NULL, 1),
(1435382, 185586, 327, '<td valign="top">Kool Arizona flag shirt!! Great colors.</td>', 'Kool Arizona flag shirt!! Great colors.', '2005-06-06 01:13:06.000000', NULL, 1),
(1435384, 185625, 772, '<td valign="top">This is a great shot.  I would have given it a 10 if you had come up with a reasonble title :)</td>', 'This is a great shot.  I would have given it a 10 if you had come up with a reasonble title :)', '2005-06-06 01:13:37.000000', NULL, 1),
(1435386, 185810, 21714, '<td valign="top">I like it a lot. Well observed and captured.</td>', 'I like it a lot. Well observed and captured.', '2005-06-06 01:13:46.000000', NULL, 1),
(1435387, 183843, 3080, '<td valign="top">Very nice focus and clarity here.  I really like how we can see all the tiny eye lashes.  lighting also appears to be good for this shot.  SKind tones are nice.  I maybe wish there were a bit more definition in her eye...looks almost entirely black.  Seems odd that way.  The idea is neat and I think you pulled it off well.  Nice angle and framin/cropping as well.  Oh, one tiny distractino is the skin colored area in the lower left hand corner.  takes away from the smoothe line of the face.  Overall neat image though.  ~Heather~</td>', 'Very nice focus and clarity here.  I really like how we can see all the tiny eye lashes.  lighting also appears to be good for this shot.  SKind tones are nice.  I maybe wish there were a bit more definition in her eye...looks almost entirely black.  Seems odd that way.  The idea is neat and I think you pulled it off well.  Nice angle and framin/cropping as well.  Oh, one tiny distractino is the skin colored area in the lower left hand corner.  takes away from the smoothe line of the face.  Overall neat image though.  ~Heather~', '2005-06-06 01:13:56.000000', NULL, 1),
