(1436289, 186045, 34194, '<td valign="top">Interesting take on the challenge and well captured.</td>', 'Interesting take on the challenge and well captured.', '2005-06-06 09:46:19.000000', NULL, 1),
(1436291, 185326, 33672, '<td valign="top">Very well done!!!  NICE comp!</td>', 'Very well done!!!  NICE comp!', '2005-06-06 09:46:57.000000', NULL, 1),
