INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1437815, 184006, 31230, '<td valign="top">Nice, I love the soft glow.  I think it definitely adds something here.  She is beautiful</td>', 'Nice, I love the soft glow.  I think it definitely adds something here.  She is beautiful', '2005-06-06 21:55:51.000000', NULL, 1),
(1437817, 185743, 35645, '<td valign="top">Cute pic of the cygnets. Crop is a little tight on the top - feels like the right hand swan is a little cramped for space. Very nice reflections and colors.</td>', 'Cute pic of the cygnets. Crop is a little tight on the top - feels like the right hand swan is a little cramped for space. Very nice reflections and colors.', '2005-06-06 21:56:13.000000', NULL, 1),
(1437820, 184933, 35645, '<td valign="top">Very clean and simple photo. Love the concept and composition. You should do a series of these and sell the prints. Very nice.</td>', 'Very clean and simple photo. Love the concept and composition. You should do a series of these and sell the prints. Very nice.', '2005-06-06 21:57:59.000000', NULL, 1),
(1437821, 185672, 31230, '<td valign="top">What cute eyes, framed by such a cute face</td>', 'What cute eyes, framed by such a cute face', '2005-06-06 21:58:43.000000', NULL, 1),
(1437823, 185417, 35645, '<td valign="top">Nice shot of the mountain. The border is very overpowering - Maybe a narrower border would not be so in-your-face.</td>', 'Nice shot of the mountain. The border is very overpowering - Maybe a narrower border would not be so in-your-face.', '2005-06-06 22:00:00.000000', NULL, 1),
(1437825, 185797, 31230, '<td valign="top">Wow, amazing sky</td>', 'Wow, amazing sky', '2005-06-06 22:00:20.000000', NULL, 1),
(1437831, 185102, 31230, '<td valign="top">Very nice color and use of your mirror to frame this beautiful scene.</td>', 'Very nice color and use of your mirror to frame this beautiful scene.', '2005-06-06 22:03:32.000000', NULL, 1),
(1437836, 185871, 35645, '<td valign="top">Cool shot. Don''t care for the processing - a simple B&amp;W or sepia tone is more my style. This feels heavy and oversaturated for the feeling of fun that the subject evokes. I would also prefer either more light or no light on the face - the details are only visible to the point where it''s kinda annoying. I love the composition.</td>', 'Cool shot. Don''t care for the processing - a simple B&W or sepia tone is more my style. This feels heavy and oversaturated for the feeling of fun that the subject evokes. I would also prefer either more light or no light on the face - the details are only visible to the point where it''s kinda annoying. I love the composition.', '2005-06-06 22:06:40.000000', NULL, 1),
(1437841, 186073, 35645, '<td valign="top">A slightly tighter crop to take out some of the ''busyness'' at the top of the pic might work to better focus on the dog. I love the position the dog is in.</td>', 'A slightly tighter crop to take out some of the ''busyness'' at the top of the pic might work to better focus on the dog. I love the position the dog is in.', '2005-06-06 22:08:10.000000', NULL, 1),
(1437853, 186056, 35645, '<td valign="top">That is a really great pic of a spider! I love the colors. Looks like the leaves are glowing. Great detail. 8.</td>', 'That is a really great pic of a spider! I love the colors. Looks like the leaves are glowing. Great detail. 8.', '2005-06-06 22:12:40.000000', NULL, 1),
(1437854, 185995, 35645, '<td valign="top">Very nice macro. Great texture and clarity. Beautiful colors.</td>', 'Very nice macro. Great texture and clarity. Beautiful colors.', '2005-06-06 22:13:37.000000', NULL, 1),
(1437862, 185673, 35645, '<td valign="top">This is a great view, but I would like to see it with a little wider crop.</td>', 'This is a great view, but I would like to see it with a little wider crop.', '2005-06-06 22:17:07.000000', NULL, 1),
(1437869, 185413, 30817, '<td valign="top">Very well seen and recorded. 9</td>', 'Very well seen and recorded. 9', '2005-06-06 22:21:36.000000', NULL, 1),
(1437871, 184167, 30817, '<td valign="top">Most enjoyable colors and a great composition in a challenge where composition is tough to get right. 9</td>', 'Most enjoyable colors and a great composition in a challenge where composition is tough to get right. 9', '2005-06-06 22:22:49.000000', NULL, 1),
(1437886, 185675, 35645, '<td valign="top">I love the expression here. Good choice of B&amp;W  - gives a more somber feel to it. I can almost see the smile wanting to come out though. Very nice.</td>', 'I love the expression here. Good choice of B&W  - gives a more somber feel to it. I can almost see the smile wanting to come out though. Very nice.', '2005-06-06 22:31:45.000000', NULL, 1),
(1437888, 185139, 35645, '<td valign="top">Very calm and serene. Puts me in mind of a Japanese water garden. Beautiful colors and clarity. Only thing I don''t like is the little bit of building in the background. Maybe a tighter crop to remove it?</td>', 'Very calm and serene. Puts me in mind of a Japanese water garden. Beautiful colors and clarity. Only thing I don''t like is the little bit of building in the background. Maybe a tighter crop to remove it?', '2005-06-06 22:33:22.000000', NULL, 1),
(1437893, 185706, 30817, '<td valign="top">I really love the subtleties at work here; subject''s posture, the suggestion more than the pronouncement of a dog, a path strewn with things not fully identified, the partially obsured horizon and the tonal shift taking place among the overhead leaves, elements all of which lend themselves to an image that whispers to me while in a competition where many times shouting for attention usually gets the desired result.  This is my favorite in this challenge and one to go in my profile pages. 10</td>', 'I really love the subtleties at work here; subject''s posture, the suggestion more than the pronouncement of a dog, a path strewn with things not fully identified, the partially obsured horizon and the tonal shift taking place among the overhead leaves, elements all of which lend themselves to an image that whispers to me while in a competition where many times shouting for attention usually gets the desired result.  This is my favorite in this challenge and one to go in my profile pages. 10', '2005-06-06 22:35:59.000000', NULL, 1),
(1437908, 185871, 36499, '<td valign="top">excellent take on the challenge! border is a little bit too think for this but doesnt take away too much from the photo. IMO this should ribbon or at least be in the top 10...good luck</td>', 'excellent take on the challenge! border is a little bit too think for this but doesnt take away too much from the photo. IMO this should ribbon or at least be in the top 10...good luck', '2005-06-06 22:46:13.000000', NULL, 1),
(1437925, 186008, 20889, '<td valign="top">I like the ideal. If the rider was more farther back, say coming up the hill or around the first turn would have framed  better, as for yourself. i don''t know where you where standing but the color seems a little flat. may try to put yourself in the shade or darken the photo some what..this is just me.</td>', 'I like the ideal. If the rider was more farther back, say coming up the hill or around the first turn would have framed  better, as for yourself. i don''t know where you where standing but the color seems a little flat. may try to put yourself in the shade or darken the photo some what..this is just me.', '2005-06-06 22:52:50.000000', NULL, 1),
(1437935, 185413, 20889, '<td valign="top">Your thinking is grand..but unlevel and this would have made a great black and white, lots of contrasting colors. stilll give you a 8.</td>', 'Your thinking is grand..but unlevel and this would have made a great black and white, lots of contrasting colors. stilll give you a 8.', '2005-06-06 22:58:25.000000', NULL, 1),
(1437943, 186022, 6667, '<td valign="top">Very nice.  8 here.   How did you get the totally black background?</td>', 'Very nice.  8 here.   How did you get the totally black background?', '2005-06-06 23:03:42.000000', NULL, 1),
(1437951, 185184, 25678, '<td valign="top">Where the sun has hit the back part of the bird is overblown though...  The spider web under the bird is a little distracting as well.  I like the composition of where the bird''s head is.</td>', 'Where the sun has hit the back part of the bird is overblown though...  The spider web under the bird is a little distracting as well.  I like the composition of where the bird''s head is.', '2005-06-06 23:08:43.000000', NULL, 1),
