(1442992, 185344, 19025, '<td valign="top">At the worst, you''ll probably get a top 5 finish...Put this in my favorites...10 from me!!</td>', 'At the worst, you''ll probably get a top 5 finish...Put this in my favorites...10 from me!!', '2005-06-09 04:30:06.000000', NULL, 1),
(1443028, 186008, 30018, '<td valign="top">This is very nicely done. &lt;7&gt;</td>', 'This is very nicely done. <7>', '2005-06-09 05:36:11.000000', NULL, 1),
(1443031, 185952, 30018, '<td valign="top">this is a very nice image as well.  I''m afraid many people will score it poorly beause it is not framed by "nature", but personally, I don''t think that is what the challenge meant.  I like it a lot.   I love all the different textures and tones.  I hope you do well.  &lt;9&gt;</td>', 'this is a very nice image as well.  I''m afraid many people will score it poorly beause it is not framed by "nature", but personally, I don''t think that is what the challenge meant.  I like it a lot.   I love all the different textures and tones.  I hope you do well.  <9>', '2005-06-09 05:38:13.000000', NULL, 1),
(1443032, 184559, 30018, '<td valign="top">Very nice composition.  Lots of wonderful colors and textures.  Good Luck  &lt;7&gt;</td>', 'Very nice composition.  Lots of wonderful colors and textures.  Good Luck  <7>', '2005-06-09 05:39:17.000000', NULL, 1),
(1443033, 186045, 30018, '<td valign="top">Very cool picture.  I''m not totally sure what is going on here.  Looks like a lot of ice.  Would love to hear more about this very interesting image.  &lt;8&gt;</td>', 'Very cool picture.  I''m not totally sure what is going on here.  Looks like a lot of ice.  Would love to hear more about this very interesting image.  <8>', '2005-06-09 05:40:35.000000', NULL, 1),
(1443034, 185951, 30018, '<td valign="top">Very nice image.  Lots of great colors and of course some wonderful textures.  &lt;8&gt;</td>', 'Very nice image.  Lots of great colors and of course some wonderful textures.  <8>', '2005-06-09 05:41:21.000000', NULL, 1),
(1443035, 185917, 30018, '<td valign="top">Very pretty and very nicely framed!  Wonderful textures in this very fine composition. &lt;8&gt;</td>', 'Very pretty and very nicely framed!  Wonderful textures in this very fine composition. <8>', '2005-06-09 05:42:46.000000', NULL, 1),
(1443038, 185570, 30018, '<td valign="top">Very nice.  I like the idea of the background or main object, being so much brighter than the frame itself.  Yet the frame has enough detail to be interesting in it''s own right.  Very nicely done.  Just might be a ribbon winner.  Good luck.  &lt;9&gt;</td>', 'Very nice.  I like the idea of the background or main object, being so much brighter than the frame itself.  Yet the frame has enough detail to be interesting in it''s own right.  Very nicely done.  Just might be a ribbon winner.  Good luck.  <9>', '2005-06-09 05:44:35.000000', NULL, 1),
(1443039, 186044, 30018, '<td valign="top">To me...this image just seems to be a little too busy.  too much to look at.  The "frame" is behind the main subject, and I think this hurts the overall image, in terms of the challenge. Otherwise, a wonderful shot of a turkey.  &lt;5&gt;</td>', 'To me...this image just seems to be a little too busy.  too much to look at.  The "frame" is behind the main subject, and I think this hurts the overall image, in terms of the challenge. Otherwise, a wonderful shot of a turkey.  <5>', '2005-06-09 05:47:17.000000', NULL, 1),
(1443040, 185995, 30018, '<td valign="top">How wonderful.  What great detail.  Fabulous texture, and very nicely framed.  Job well done.  &lt;8&gt;</td>', 'How wonderful.  What great detail.  Fabulous texture, and very nicely framed.  Job well done.  <8>', '2005-06-09 05:48:15.000000', NULL, 1),
(1443042, 185497, 30018, '<td valign="top">I"m not sure one can get much lower than this.  This is a great shot.  Florida baseball might use this in there advertising.  Interesting framed.  I like the grass frame, but the palm trees "behind" the baseball just don''t feel right to me, because they are behind.  That''s just me.  I think this is a wonderful image, and I hope it does well.  &lt;7&gt;</td>', 'I"m not sure one can get much lower than this.  This is a great shot.  Florida baseball might use this in there advertising.  Interesting framed.  I like the grass frame, but the palm trees "behind" the baseball just don''t feel right to me, because they are behind.  That''s just me.  I think this is a wonderful image, and I hope it does well.  <7>', '2005-06-09 05:50:56.000000', NULL, 1),
(1443280, 185718, 37851, '<td valign="top">Beautiful shot.  I love the shadows.</td>', 'Beautiful shot.  I love the shadows.', '2005-06-09 09:02:34.000000', NULL, 1),
(1443284, 186064, 37851, '<td valign="top">I like this picture, but I just find the tilt of the birdhouse(?)  to be a bit distracting.  I want to reach in and straighten it!<br/></td>', 'I like this picture, but I just find the tilt of the birdhouse(?)  to be a bit distracting.  I want to reach in and straighten it!', '2005-06-09 09:05:16.000000', NULL, 1),
(1443288, 184559, 37851, '<td valign="top">I wish the top right corner was just a little bit lighter, but still a wonderful picture for this challange.</td>', 'I wish the top right corner was just a little bit lighter, but still a wonderful picture for this challange.', '2005-06-09 09:07:39.000000', NULL, 1),
(1443396, 183997, 34402, '<td valign="top">What a beautiful picture!</td>', 'What a beautiful picture!', '2005-06-09 09:59:14.000000', NULL, 1),
(1443399, 185931, 27475, '<td valign="top">Hmmmmmm to young to eat... ;)</td>', 'Hmmmmmm to young to eat... ;)', '2005-06-09 10:00:33.000000', NULL, 1),
(1443427, 185871, 22734, '<td valign="top">Awesome and daring capture. 7 on first round. <br/>A very special effort with a unique concept. The post processing leaves a little to be desired but it is perhaps the best that can be done to present image as a silhoutte. You have my 9</td>', 'Awesome and daring capture. 7 on first round. A very special effort with a unique concept. The post processing leaves a little to be desired but it is perhaps the best that can be done to present image as a silhoutte. You have my 9', '2005-06-09 10:32:08.000000', NULL, 1),
(1443452, 185753, 31443, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2005-06-09 10:50:27.000000', NULL, 1),
(1443457, 186037, 31443, '<td valign="top">Fantastic shot</td>', 'Fantastic shot', '2005-06-09 10:57:30.000000', NULL, 1),
(1443459, 185883, 31443, '<td valign="top">Don´t know about the frame here but the building is impressive</td>', 'Don´t know about the frame here but the building is impressive', '2005-06-09 11:03:26.000000', NULL, 1),
(1443466, 185647, 24546, '<td valign="top">Your idea here was good -  these lovely old trees certainly frame the road well.  But the photo is over exposed - the brightest areas are "blown out".</td>', 'Your idea here was good -  these lovely old trees certainly frame the road well.  But the photo is over exposed - the brightest areas are "blown out".', '2005-06-09 11:09:39.000000', NULL, 1),
(1443472, 185173, 24546, '<td valign="top">This was such a great idea, but your lighting is too harsh and it is over exposed.</td>', 'This was such a great idea, but your lighting is too harsh and it is over exposed.', '2005-06-09 11:12:27.000000', NULL, 1),
(1443473, 186022, 24546, '<td valign="top">Great idea, nice and sharp. But your lighting is way too harsh and this one feels very over exposed.</td>', 'Great idea, nice and sharp. But your lighting is way too harsh and this one feels very over exposed.', '2005-06-09 11:15:10.000000', NULL, 1),
(1443476, 184167, 35739, '<td valign="top">Wish the people were in focus rather than the frame. Nice content.</td>', 'Wish the people were in focus rather than the frame. Nice content.', '2005-06-09 11:21:00.000000', NULL, 1),
(1443480, 185642, 35739, '<td valign="top">I believe the building being in focus more so than the frame may have been better?<br/></td>', 'I believe the building being in focus more so than the frame may have been better?', '2005-06-09 11:26:39.000000', NULL, 1),
(1443482, 185631, 24546, '<td valign="top">Those twiggy branches at the top are a distracting element - It is always important to sweep the edges of your frame before you take your shot. The shot would be stronger if you cloned them out.</td>', 'Those twiggy branches at the top are a distracting element - It is always important to sweep the edges of your frame before you take your shot. The shot would be stronger if you cloned them out.', '2005-06-09 11:29:17.000000', NULL, 1),
(1443484, 185866, 35739, '<td valign="top">I believe the equipment should have been in focus.</td>', 'I believe the equipment should have been in focus.', '2005-06-09 11:29:58.000000', NULL, 1),
(1443486, 185798, 35739, '<td valign="top">Nice try.  Too small.</td>', 'Nice try.  Too small.', '2005-06-09 11:31:01.000000', NULL, 1),
(1443489, 185753, 35739, '<td valign="top">Top 20 image Im sure.</td>', 'Top 20 image Im sure.', '2005-06-09 11:32:55.000000', NULL, 1),
(1443492, 185931, 35739, '<td valign="top">A little overexposed? Not sure.  I do like the photo alot.  Good job.</td>', 'A little overexposed? Not sure.  I do like the photo alot.  Good job.', '2005-06-09 11:34:19.000000', NULL, 1),
(1443495, 185871, 35739, '<td valign="top">Sure to a Ribbon winner here.  Good job.</td>', 'Sure to a Ribbon winner here.  Good job.', '2005-06-09 11:35:54.000000', NULL, 1),
(1443502, 185013, 27901, '<td valign="top">Wow, what a picture, this is fantastic, you are taking this one just at the right moment and your handle of the fire is simply fantastic.</td>', 'Wow, what a picture, this is fantastic, you are taking this one just at the right moment and your handle of the fire is simply fantastic.', '2005-06-09 11:39:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1443504, 184006, 27901, '<td valign="top">Beautiful picture I like the soft tone, but I am not sure I can agree that it is naturally framed though, but maybe the water...</td>', 'Beautiful picture I like the soft tone, but I am not sure I can agree that it is naturally framed though, but maybe the water...', '2005-06-09 11:40:10.000000', NULL, 1),
