(1443513, 185969, 27901, '<td valign="top">Artistic shot! although the framing is mabe not a key in the picture there is certainly a frame in it although not of the subject as one would expect. But great picture and the balance just great.</td>', 'Artistic shot! although the framing is mabe not a key in the picture there is certainly a frame in it although not of the subject as one would expect. But great picture and the balance just great.', '2005-06-09 11:44:12.000000', NULL, 1),
(1443514, 185810, 27901, '<td valign="top">Clever thought and good shot!</td>', 'Clever thought and good shot!', '2005-06-09 11:44:34.000000', NULL, 1),
(1443516, 185743, 27901, '<td valign="top">Yes they are framed by their parents, beautiful picture.</td>', 'Yes they are framed by their parents, beautiful picture.', '2005-06-09 11:44:50.000000', NULL, 1),
(1443517, 185310, 27901, '<td valign="top">This is one of the best here in this challenge, this artistic setup and framing is very cleverly done.</td>', 'This is one of the best here in this challenge, this artistic setup and framing is very cleverly done.', '2005-06-09 11:45:13.000000', NULL, 1),
(1443520, 185866, 27901, '<td valign="top">Cool! I like how you do this and to put the tools so high in the circle and the water with mirroring poles in the front.</td>', 'Cool! I like how you do this and to put the tools so high in the circle and the water with mirroring poles in the front.', '2005-06-09 11:45:45.000000', NULL, 1),
