(1447161, 185904, 27399, '<td valign="top">Brilliant!  Great eye!  I would have moved it a little more to the right, to get all of that mushroomy thing in the shot, especially since the far left doesn''t add much worth cutting out the right.  Excellent job though.</td>', 'Brilliant!  Great eye!  I would have moved it a little more to the right, to get all of that mushroomy thing in the shot, especially since the far left doesn''t add much worth cutting out the right.  Excellent job though.', '2005-06-11 06:16:57.000000', NULL, 1),
(1447163, 185753, 27399, '<td valign="top">Could have framed it a little bit higher, getting rid of the unecessary grass at the bottom while completing the arch at the top.  Nice shot.</td>', 'Could have framed it a little bit higher, getting rid of the unecessary grass at the bottom while completing the arch at the top.  Nice shot.', '2005-06-11 06:18:51.000000', NULL, 1),
