(1447225, 185871, 16636, '<td valign="top">If this is not imagineer''s image I will be more surprised than if this does not win. Awsome shot (jon?), although I don''t like the colouration, far too saturated for my taste, the image stands head and shoulders above the rest - 10</td>', 'If this is not imagineer''s image I will be more surprised than if this does not win. Awsome shot (jon?), although I don''t like the colouration, far too saturated for my taste, the image stands head and shoulders above the rest - 10', '2005-06-11 08:21:19.000000', NULL, 1),
(1447261, 185831, 32997, '<td valign="top">Nice capture!</td>', 'Nice capture!', '2005-06-11 09:24:32.000000', NULL, 1),
(1447272, 185840, 2764, '<td valign="top">he seems crowded at the top of the photo - maybe crop him some more headroom in case he wants to jump?  moving him down in the frame would improve the composition .</td>', 'he seems crowded at the top of the photo - maybe crop him some more headroom in case he wants to jump?  moving him down in the frame would improve the composition .', '2005-06-11 09:31:38.000000', NULL, 1),
(1447276, 185557, 2764, '<td valign="top">oh dear - a wonderfully lovely image spoiled by an extra border.  Your foliage does an excellent job of framing the scene, the green border is unnecessary.</td>', 'oh dear - a wonderfully lovely image spoiled by an extra border.  Your foliage does an excellent job of framing the scene, the green border is unnecessary.', '2005-06-11 09:34:02.000000', NULL, 1),
(1447281, 184883, 2764, '<td valign="top">not sure this frame works - it is so heavy compared to the bird plus it is not in focus. what if you increased the saturation on the bird so that he stands out more?  he is too similar in color to the bamboo.</td>', 'not sure this frame works - it is so heavy compared to the bird plus it is not in focus. what if you increased the saturation on the bird so that he stands out more?  he is too similar in color to the bamboo.', '2005-06-11 09:36:54.000000', NULL, 1),
(1447300, 185782, 39120, '<td valign="top">Wow really nice job !</td>', 'Wow really nice job !', '2005-06-11 10:07:07.000000', NULL, 1),
(1447357, 185982, 37005, '<td valign="top">The foreground exposure seems a bit harsh but it''s a good concept.</td>', 'The foreground exposure seems a bit harsh but it''s a good concept.', '2005-06-11 10:57:25.000000', NULL, 1),
(1447367, 183740, 30185, '<td valign="top">Good Job With This One I Love The Reflection</td>', 'Good Job With This One I Love The Reflection', '2005-06-11 11:03:54.000000', NULL, 1),
(1447481, 185884, 32196, '<td valign="top">the flower lacks sharpness..</td>', 'the flower lacks sharpness..', '2005-06-11 12:20:26.000000', NULL, 1),
(1447554, 185928, 31443, '<td valign="top">There is something colorful and mysterious about old junk and this one sure is colorful, like it lots</td>', 'There is something colorful and mysterious about old junk and this one sure is colorful, like it lots', '2005-06-11 13:08:36.000000', NULL, 1),
(1447577, 185718, 31443, '<td valign="top">Nice warm colors of summer, lovely!</td>', 'Nice warm colors of summer, lovely!', '2005-06-11 13:31:15.000000', NULL, 1),
(1447582, 184504, 22689, '<td valign="top">She''s so cute (as always !).</td>', 'She''s so cute (as always !).', '2005-06-11 13:38:16.000000', NULL, 1),
(1447691, 185832, 24212, '<td valign="top">I like this, but, on my monitor at least, the bird looks to be a little washed out.</td>', 'I like this, but, on my monitor at least, the bird looks to be a little washed out.', '2005-06-11 14:59:10.000000', NULL, 1),
(1447692, 185857, 24212, '<td valign="top">I like the framing, but feel that the waterfall does not appear to be sharp or ''punchy'' enough.</td>', 'I like the framing, but feel that the waterfall does not appear to be sharp or ''punchy'' enough.', '2005-06-11 15:00:09.000000', NULL, 1),
(1447693, 185995, 24212, '<td valign="top">A very nice macro. Possibly a little too centred (even though that''s how I normally frame my shots).</td>', 'A very nice macro. Possibly a little too centred (even though that''s how I normally frame my shots).', '2005-06-11 15:01:00.000000', NULL, 1),
(1447694, 185976, 24212, '<td valign="top">Nicely done. The comparative softness of the shell above and below really makes the face stand out.</td>', 'Nicely done. The comparative softness of the shell above and below really makes the face stand out.', '2005-06-11 15:02:08.000000', NULL, 1),
(1447696, 185929, 24212, '<td valign="top">I like the contrast here and the way that it is the background doing the framing.</td>', 'I like the contrast here and the way that it is the background doing the framing.', '2005-06-11 15:02:58.000000', NULL, 1),
(1447697, 185587, 24212, '<td valign="top">A neat idea, although I''d prefer to see the right-hand side of the frame a little brighter.</td>', 'A neat idea, although I''d prefer to see the right-hand side of the frame a little brighter.', '2005-06-11 15:03:57.000000', NULL, 1),
(1447698, 184305, 24212, '<td valign="top">I''m not sure that so much background outside the mirror is really necessary.</td>', 'I''m not sure that so much background outside the mirror is really necessary.', '2005-06-11 15:05:31.000000', NULL, 1),
(1447699, 186054, 24212, '<td valign="top">I like the way that the boom (cement pump?) stands out in the middle, although I feel that the chimney rather detracts from the effect.</td>', 'I like the way that the boom (cement pump?) stands out in the middle, although I feel that the chimney rather detracts from the effect.', '2005-06-11 15:06:47.000000', NULL, 1),
(1447701, 185557, 24212, '<td valign="top">A very nice scenic view, although I''d perhaps prefer to see the centre of the frame a little sharper.</td>', 'A very nice scenic view, although I''d perhaps prefer to see the centre of the frame a little sharper.', '2005-06-11 15:07:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1447704, 185349, 24212, '<td valign="top">I like the view here. I wonder how it would look without the two lamp columns (or at least half-columns) either side of the arch.</td>', 'I like the view here. I wonder how it would look without the two lamp columns (or at least half-columns) either side of the arch.', '2005-06-11 15:09:49.000000', NULL, 1),
(1447705, 185718, 24212, '<td valign="top">I think that the colours are great, althought the right hand side of the frame is a little lacking in interest.</td>', 'I think that the colours are great, althought the right hand side of the frame is a little lacking in interest.', '2005-06-11 15:10:52.000000', NULL, 1),
(1447706, 185978, 24212, '<td valign="top">If anything, I''d perhaps like to see the swan a bit sharper.</td>', 'If anything, I''d perhaps like to see the swan a bit sharper.', '2005-06-11 15:11:36.000000', NULL, 1),
(1447709, 185957, 24212, '<td valign="top">A good idea. I wonder how it would look if the cyclist were to be a little further back in the frame.</td>', 'A good idea. I wonder how it would look if the cyclist were to be a little further back in the frame.', '2005-06-11 15:12:44.000000', NULL, 1),
(1447710, 186046, 24212, '<td valign="top">I think that this has a real ''sunny afternoon'' feel to it, although I really don''t get an impression of ''framedness''. Still a very attractive photo.</td>', 'I think that this has a real ''sunny afternoon'' feel to it, although I really don''t get an impression of ''framedness''. Still a very attractive photo.', '2005-06-11 15:14:26.000000', NULL, 1),
(1447715, 185732, 24212, '<td valign="top">A great crop, although it doesn''t look to be quite sharp enough to me.</td>', 'A great crop, although it doesn''t look to be quite sharp enough to me.', '2005-06-11 15:24:28.000000', NULL, 1),
(1447716, 185534, 24212, '<td valign="top">To me, the tree looks to be sharper than the squirrel (and, indeed, the ground around the squirrel). Was the focus point deliberately behind?</td>', 'To me, the tree looks to be sharper than the squirrel (and, indeed, the ground around the squirrel). Was the focus point deliberately behind?', '2005-06-11 15:26:35.000000', NULL, 1),
(1447718, 186056, 24212, '<td valign="top">I would really like to see the spider''s forelegs in sharper focus.</td>', 'I would really like to see the spider''s forelegs in sharper focus.', '2005-06-11 15:27:26.000000', NULL, 1),
(1447720, 185556, 35804, '<td valign="top">Completely exquisite...wonderful lush color and velvety rich blacks...also very effective as an abstract...also, the black makes me think of this as an unfinished painting, or a painting that was finished and is being painted over with black, just a really nice simple composition...this is certainly on of my favorites</td>', 'Completely exquisite...wonderful lush color and velvety rich blacks...also very effective as an abstract...also, the black makes me think of this as an unfinished painting, or a painting that was finished and is being painted over with black, just a really nice simple composition...this is certainly on of my favorites', '2005-06-11 15:30:29.000000', NULL, 1),
(1447724, 184558, 24212, '<td valign="top">To me, the dolphin doesn''t stand out from the background quite enough. A bit of blurring of the background, maybe?</td>', 'To me, the dolphin doesn''t stand out from the background quite enough. A bit of blurring of the background, maybe?', '2005-06-11 15:32:22.000000', NULL, 1),
(1447725, 184167, 32754, '<td valign="top">I like the bridge framing these colorful umbrellas..and the symmetry of this shot.</td>', 'I like the bridge framing these colorful umbrellas..and the symmetry of this shot.', '2005-06-11 15:32:24.000000', NULL, 1),
(1447726, 184933, 35804, '<td valign="top">Such pretty light, the texture of those leaves is wonderful, they look as though they are made of silk...very subtle...nicely done.</td>', 'Such pretty light, the texture of those leaves is wonderful, they look as though they are made of silk...very subtle...nicely done.', '2005-06-11 15:32:32.000000', NULL, 1),
(1447727, 185979, 24212, '<td valign="top">The outlines of the silhouettes are almost unbelievably crisp. I love the sunset colours. Possibly a little  more of a crop at the bottom of the frame?</td>', 'The outlines of the silhouettes are almost unbelievably crisp. I love the sunset colours. Possibly a little  more of a crop at the bottom of the frame?', '2005-06-11 15:33:57.000000', NULL, 1),
(1447729, 185968, 24212, '<td valign="top">Great colours in the sky.</td>', 'Great colours in the sky.', '2005-06-11 15:34:30.000000', NULL, 1),
(1447731, 185807, 35804, '<td valign="top">I gotta say it...AMAZING!..I don''t think I have ever seen a macro shot of a cat''s eye like this...so so very close...like I''m looking into some other world...a really wonderful image.</td>', 'I gotta say it...AMAZING!..I don''t think I have ever seen a macro shot of a cat''s eye like this...so so very close...like I''m looking into some other world...a really wonderful image.', '2005-06-11 15:34:53.000000', NULL, 1),
(1447732, 185373, 24212, '<td valign="top">I like the placement of the clocktower in the frame. It just looks a little soft, though.</td>', 'I like the placement of the clocktower in the frame. It just looks a little soft, though.', '2005-06-11 15:35:48.000000', NULL, 1),
(1447734, 185782, 24212, '<td valign="top">I don''t really get a sens of ''framed'', but I''ve got to give this a good score just for the stunning sky.</td>', 'I don''t really get a sens of ''framed'', but I''ve got to give this a good score just for the stunning sky.', '2005-06-11 15:37:08.000000', NULL, 1),
(1447735, 186022, 24212, '<td valign="top">The texture in the fence is great, although I feel that the lighting may be a little too harsh.</td>', 'The texture in the fence is great, although I feel that the lighting may be a little too harsh.', '2005-06-11 15:38:02.000000', NULL, 1),
(1447738, 185728, 35804, '<td valign="top">Gorgeous light and texture...the image has a great mysterious aura about it...maybe  think brought about by the two people standing at the top of the image? I''m not sure,  but I am sure this is one of my favorites...nicely done.</td>', 'Gorgeous light and texture...the image has a great mysterious aura about it...maybe  think brought about by the two people standing at the top of the image? I''m not sure,  but I am sure this is one of my favorites...nicely done.', '2005-06-11 15:39:20.000000', NULL, 1),
(1447741, 184509, 24212, '<td valign="top">A very interesting find and well shot with the blur in the water. However, I find the composition a little uninteresting. Perhaps a little too centred, even though I tend to compose most of my shots like that.</td>', 'A very interesting find and well shot with the blur in the water. However, I find the composition a little uninteresting. Perhaps a little too centred, even though I tend to compose most of my shots like that.', '2005-06-11 15:40:24.000000', NULL, 1),
(1447745, 185951, 24212, '<td valign="top">A great ''texture'' shot. I''d really like to see the context from which this came.</td>', 'A great ''texture'' shot. I''d really like to see the context from which this came.', '2005-06-11 15:41:39.000000', NULL, 1),
(1447750, 185560, 35804, '<td valign="top">This picture makes me feel as if I am close to disturbing this lovely interlude...such a beautiful image...so soft and quiet...almost like a precious stolen moment has been permanently captured and saved forever...I also like the way you have processed this image...it has a very "dreamy " feel about it...nicely done.</td>', 'This picture makes me feel as if I am close to disturbing this lovely interlude...such a beautiful image...so soft and quiet...almost like a precious stolen moment has been permanently captured and saved forever...I also like the way you have processed this image...it has a very "dreamy " feel about it...nicely done.', '2005-06-11 15:45:15.000000', NULL, 1),
(1447754, 184973, 24212, '<td valign="top">Very sharp and colourful and the framing is great, athough I don''t feel that the silhouetted figure really adds to the effect.</td>', 'Very sharp and colourful and the framing is great, athough I don''t feel that the silhouetted figure really adds to the effect.', '2005-06-11 15:47:10.000000', NULL, 1),
(1447757, 186033, 24212, '<td valign="top">I''m not sure that I really like the bridge behind being soft like that.</td>', 'I''m not sure that I really like the bridge behind being soft like that.', '2005-06-11 15:48:08.000000', NULL, 1),
(1447764, 185013, 24212, '<td valign="top">Great capture. Normally it is very easy to get the flames hideously overexposed in relation to the rest of the frame.I like the way that the ''bike is level and that there are those trails of flame on the right of the frame.</td>', 'Great capture. Normally it is very easy to get the flames hideously overexposed in relation to the rest of the frame.I like the way that the ''bike is level and that there are those trails of flame on the right of the frame.', '2005-06-11 15:50:07.000000', NULL, 1),
(1447765, 185135, 35804, '<td valign="top">Beautiful "inky" blues and blacks...this image has a beautiful lush abstract quality about it...{{{long pause}}}... those blues are just yummy... if blue ever was.</td>', 'Beautiful "inky" blues and blacks...this image has a beautiful lush abstract quality about it...{{{long pause}}}... those blues are just yummy... if blue ever was.', '2005-06-11 15:51:10.000000', NULL, 1),
(1447766, 183795, 24212, '<td valign="top">Great composition. I love the simple lines.</td>', 'Great composition. I love the simple lines.', '2005-06-11 15:51:17.000000', NULL, 1),
(1447771, 185136, 35804, '<td valign="top">I really like this image..particularly the "harsh" lighting...it has a great candid feel about it...the stripped shirt makes it even more interesting.</td>', 'I really like this image..particularly the "harsh" lighting...it has a great candid feel about it...the stripped shirt makes it even more interesting.', '2005-06-11 15:54:21.000000', NULL, 1),
(1447811, 185807, 25655, '<td valign="top">wooooow!!! How did you manage to capture this??? amazing!!!<br/>I am comlpetely speechless!<br/>Got the idea re the challenge, and simlpy amazed by this unique capture.<br/>10 and streight into my favorites!<br/></td>', 'wooooow!!! How did you manage to capture this??? amazing!!!I am comlpetely speechless!Got the idea re the challenge, and simlpy amazed by this unique capture.10 and streight into my favorites!', '2005-06-11 16:59:01.000000', NULL, 1),
(1447854, 185058, 31005, '<td valign="top">2nd time around, I think it''s a great shot and how awesome you were there to catch it.  Bumping up, good luck.</td>', '2nd time around, I think it''s a great shot and how awesome you were there to catch it.  Bumping up, good luck.', '2005-06-11 17:26:23.000000', NULL, 1),
(1447879, 185840, 8860, '<td valign="top">Great subject - love frogs, and he looks marvellous.</td>', 'Great subject - love frogs, and he looks marvellous.', '2005-06-11 17:44:15.000000', NULL, 1),
(1447883, 185201, 8860, '<td valign="top">Great capture and a real sense of naturalist voyeurism.</td>', 'Great capture and a real sense of naturalist voyeurism.', '2005-06-11 17:55:19.000000', NULL, 1),
(1447885, 185953, 8860, '<td valign="top">I see it! I see it!<br/>: )</td>', 'I see it! I see it!: )', '2005-06-11 17:56:38.000000', NULL, 1),
(1447887, 185058, 8860, '<td valign="top">Brilliant! Should be a winner for opportunism alone. Great stuff.</td>', 'Brilliant! Should be a winner for opportunism alone. Great stuff.', '2005-06-11 17:58:02.000000', NULL, 1),
(1447890, 185807, 8860, '<td valign="top">Utterly jaw-dropping image. Striking colour and subject and I love the approach to the challenge. (Yet another) fave.</td>', 'Utterly jaw-dropping image. Striking colour and subject and I love the approach to the challenge. (Yet another) fave.', '2005-06-11 18:00:17.000000', NULL, 1),
(1447910, 186069, 8860, '<td valign="top">Crazy scene! What''s the story here?</td>', 'Crazy scene! What''s the story here?', '2005-06-11 18:19:09.000000', NULL, 1),
(1447911, 185931, 3306, '<td valign="top">Wonderful capture</td>', 'Wonderful capture', '2005-06-11 18:20:26.000000', NULL, 1),
(1447913, 185797, 3306, '<td valign="top">Incredible sky</td>', 'Incredible sky', '2005-06-11 18:22:25.000000', NULL, 1),
(1447914, 186066, 25655, '<td valign="top">umm.... wrong challenge!! ;-)<br/> <br/>Wonderful capture, framed beautifully. 7</td>', 'umm.... wrong challenge!! ;-) Wonderful capture, framed beautifully. 7', '2005-06-11 18:22:41.000000', NULL, 1),
(1447919, 185915, 25655, '<td valign="top">lately I''ve found myself voting down of flora shots. kinda corney...<br/>But this one is beautiful. Got my attention streight away!<br/>I love the process on the flower, the focus and DOF are perfect  and the tiny white flowers framing all around are just wonderful. <br/>simlpe but affective. 8</td>', 'lately I''ve found myself voting down of flora shots. kinda corney...But this one is beautiful. Got my attention streight away!I love the process on the flower, the focus and DOF are perfect  and the tiny white flowers framing all around are just wonderful. simlpe but affective. 8', '2005-06-11 18:25:44.000000', NULL, 1),
(1447925, 184504, 25655, '<td valign="top">Fits the challenge nicely.<br/>Personally, I don''t like this dreamy blur in here. I would prefer to see the little girl in crisp focus. <br/>But her expression worth a million. Couldn''t help it! 7</td>', 'Fits the challenge nicely.Personally, I don''t like this dreamy blur in here. I would prefer to see the little girl in crisp focus. But her expression worth a million. Couldn''t help it! 7', '2005-06-11 18:27:34.000000', NULL, 1),
(1447927, 185807, 3306, '<td valign="top">Awesome shot. 10</td>', 'Awesome shot. 10', '2005-06-11 18:27:55.000000', NULL, 1),
(1447928, 186045, 3306, '<td valign="top">very good. Great capture. One of my favorites</td>', 'very good. Great capture. One of my favorites', '2005-06-11 18:28:26.000000', NULL, 1),
(1447932, 185871, 3306, '<td valign="top">Excellent capture. Interesting filter. One of my top 3 picks.</td>', 'Excellent capture. Interesting filter. One of my top 3 picks.', '2005-06-11 18:29:38.000000', NULL, 1),
(1447935, 185557, 22537, '<td valign="top">This is a beautiful image and it certainly meets the challenge. It is well saturated and quite sharp.  I like the use of colors but I find the shed/shack in the foreground to be quite unappealing.  Good luck</td>', 'This is a beautiful image and it certainly meets the challenge. It is well saturated and quite sharp.  I like the use of colors but I find the shed/shack in the foreground to be quite unappealing.  Good luck', '2005-06-11 18:30:40.000000', NULL, 1),
(1447937, 185383, 38408, '<td valign="top">This is gorgeous!</td>', 'This is gorgeous!', '2005-06-11 18:32:22.000000', NULL, 1),
(1447938, 186065, 22537, '<td valign="top">The colors in this shot are vivid and I agree that this chap is framed in colors but I think this shot may bode better in another challenge besides this.  Either way, beautiful capture.  Good luck!</td>', 'The colors in this shot are vivid and I agree that this chap is framed in colors but I think this shot may bode better in another challenge besides this.  Either way, beautiful capture.  Good luck!', '2005-06-11 18:32:47.000000', NULL, 1),
(1447939, 185507, 33672, '<td valign="top">Nice selective desat</td>', 'Nice selective desat', '2005-06-11 18:32:51.000000', NULL, 1),
(1447942, 186045, 33672, '<td valign="top">This concept is hard to pull off, but you''ve done this well. One of my top scorers!</td>', 'This concept is hard to pull off, but you''ve done this well. One of my top scorers!', '2005-06-11 18:34:10.000000', NULL, 1),
(1447944, 184594, 22537, '<td valign="top">Good capture of the frog though I wish the plant life in which he is nestled was in as good health as him.   I found that to be somewhat of a  detracting element of this well framed image.</td>', 'Good capture of the frog though I wish the plant life in which he is nestled was in as good health as him.   I found that to be somewhat of a  detracting element of this well framed image.', '2005-06-11 18:34:54.000000', NULL, 1),
(1447945, 186045, 22537, '<td valign="top">This is one of the most creative shots in this challege and I had to look quite hard to figure what it was. That aside, it meets the challenge though the colors, due to the asphalt, are quite dreary and do an injustice to this artful shot.  Good luck!</td>', 'This is one of the most creative shots in this challege and I had to look quite hard to figure what it was. That aside, it meets the challenge though the colors, due to the asphalt, are quite dreary and do an injustice to this artful shot.  Good luck!', '2005-06-11 18:36:37.000000', NULL, 1),
(1447946, 185613, 33672, '<td valign="top">Incredible capture... the type of photo I hope to get.... However thr focus seems to be on the right tree and not the moose,  I like the reflection and the comp very much.</td>', 'Incredible capture... the type of photo I hope to get.... However thr focus seems to be on the right tree and not the moose,  I like the reflection and the comp very much.', '2005-06-11 18:37:09.000000', NULL, 1),
(1447947, 185417, 22537, '<td valign="top">This is a beautiful shot.  The frame is a bit too wide for my liking and had you cloned out the spot on the far left, i''d have been more forgiving. This shot certainly deserves to be re-editted and included as a showpiece in your portfiolio.  Good luck!</td>', 'This is a beautiful shot.  The frame is a bit too wide for my liking and had you cloned out the spot on the far left, i''d have been more forgiving. This shot certainly deserves to be re-editted and included as a showpiece in your portfiolio.  Good luck!', '2005-06-11 18:38:25.000000', NULL, 1),
(1447949, 185777, 22537, '<td valign="top">This shot meets the challenge quite well though I see you had some struggle with the widely varied exposure.  A fill flash may have helped to lighten your subject and even out the image.  I hope you do well.  Good luck.</td>', 'This shot meets the challenge quite well though I see you had some struggle with the widely varied exposure.  A fill flash may have helped to lighten your subject and even out the image.  I hope you do well.  Good luck.', '2005-06-11 18:40:34.000000', NULL, 1),
(1447950, 185883, 22537, '<td valign="top">This image is sharp and the colors are pleasant.  I agree that the trees do frame the shot but a slightly more interesting subject may have been chosen. Good luck!</td>', 'This image is sharp and the colors are pleasant.  I agree that the trees do frame the shot but a slightly more interesting subject may have been chosen. Good luck!', '2005-06-11 18:41:51.000000', NULL, 1),
(1447953, 184899, 22537, '<td valign="top">Firstly, I think cows are fun and willing subjects for any shot.  I have far too many of them in my collection. The image is humorous and sharp though you might have cropped a bit tighter to balance out the frame.  Good luck!</td>', 'Firstly, I think cows are fun and willing subjects for any shot.  I have far too many of them in my collection. The image is humorous and sharp though you might have cropped a bit tighter to balance out the frame.  Good luck!', '2005-06-11 18:47:21.000000', NULL, 1),
(1447955, 185383, 37719, '<td valign="top">I like the photo and this is is a great shot of the child.  But that is what it is.  The challenge said ''naturally'' framed and I highly doubt this is natural.</td>', 'I like the photo and this is is a great shot of the child.  But that is what it is.  The challenge said ''naturally'' framed and I highly doubt this is natural.', '2005-06-11 18:48:18.000000', NULL, 1),
(1447958, 184536, 37719, '<td valign="top">I knew we would see the glasses shots.  I was hoping to see on from the other perspective though - looking through not into.  Technically it is a good photo.  I just don''t think it entirely meets the challenge.  Not that it influenced my voting, but if you had done the picture the other way, I would agree with your title.  But as it is it is framing your eye, not your world view.</td>', 'I knew we would see the glasses shots.  I was hoping to see on from the other perspective though - looking through not into.  Technically it is a good photo.  I just don''t think it entirely meets the challenge.  Not that it influenced my voting, but if you had done the picture the other way, I would agree with your title.  But as it is it is framing your eye, not your world view.', '2005-06-11 18:50:42.000000', NULL, 1),
