(1448179, 185570, 15711, '<td valign="top">I like the vivid greens and oranges of the background. Nice!!!</td>', 'I like the vivid greens and oranges of the background. Nice!!!', '2005-06-11 20:58:54.000000', NULL, 1),
(1448180, 184774, 15711, '<td valign="top">Lovely shot. I like the added colors in the oranges and reds. Crisp focus - well done.</td>', 'Lovely shot. I like the added colors in the oranges and reds. Crisp focus - well done.', '2005-06-11 20:59:26.000000', NULL, 1),
(1448181, 185871, 15711, '<td valign="top">This is terrific. So hard to do a stop action and get it within a "target" as you''ve done with the ferris wheel.  Nicely done!!! This could be a ribbon winner.</td>', 'This is terrific. So hard to do a stop action and get it within a "target" as you''ve done with the ferris wheel.  Nicely done!!! This could be a ribbon winner.', '2005-06-11 21:00:07.000000', NULL, 1),
(1448182, 184899, 25754, '<td valign="top">hahaha I love this shot. what a wonderful expression!<br/>I would have cropped off the top green portion to match the cropping of the bar below.</td>', 'hahaha I love this shot. what a wonderful expression!I would have cropped off the top green portion to match the cropping of the bar below.', '2005-06-11 21:00:33.000000', NULL, 1),
(1448183, 185951, 33947, '<td valign="top">Meets challenge very well. Colors of bark are nice and rich, but, the color on the wood part seems harsh and too intense. I like the dark contast in the splits of the wood.</td>', 'Meets challenge very well. Colors of bark are nice and rich, but, the color on the wood part seems harsh and too intense. I like the dark contast in the splits of the wood.', '2005-06-11 21:00:51.000000', NULL, 1),
(1448195, 185816, 15711, '<td valign="top">Very nice shot.</td>', 'Very nice shot.', '2005-06-11 21:09:48.000000', NULL, 1),
