(1448484, 184558, 30490, '<td valign="top">Nice capture but doesn''t seem to fit the challenge very closely.  How is the dolphin being framed?</td>', 'Nice capture but doesn''t seem to fit the challenge very closely.  How is the dolphin being framed?', '2005-06-12 00:22:04.000000', NULL, 1),
(1448487, 186046, 30490, '<td valign="top">Usually the most interstesting part of the image will be within the frame.  Using the arm and face as the frame, there is nothing in your frame.</td>', 'Usually the most interstesting part of the image will be within the frame.  Using the arm and face as the frame, there is nothing in your frame.', '2005-06-12 00:23:01.000000', NULL, 1),
