INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1452251, 185753, 16636, '<td valign="top">The image from which I cropped the challenge entry is:<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=189162" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/16636/thumb/189162.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/16636/thumb/189162.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/16636/thumb/189162.jpg"/></a> <br/> <br/>and the version with the windmill sail removed:<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=189308" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/16636/thumb/189308.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/16636/thumb/189308.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/16636/thumb/189308.jpg"/></a> <br/> <br/>Cheers,<br/><b>Nordic</b><br/><br/><i>Message edited by author 2005-06-13 14:02:46.</i></td>', 'The image from which I cropped the challenge entry is:   and the version with the windmill sail removed:   Cheers,Nordic', '2005-06-13 14:58:17.000000', '2005-06-13 15:02:46.000000', 0),
